insert into ponew values
(1, 1, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Meconium ileus in a newborn is strongly associated with:', '["Sickle cell disease", "Cystic fibrosis", "Hypothyroidism", "Down syndrome"]'::jsonb, 1, 'Thick meconium blocks the ileum.', 'PON 423 · Paediatric Surgery'),
(1, 2, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A baby with congenital diaphragmatic hernia at birth should NOT receive:', '["A nasogastric tube to decompress the stomach", "Prolonged bag-and-mask ventilation", "Warmth and monitoring", "Intubation and gentle ventilation"]'::jsonb, 1, 'Mask ventilation fills the bowel in the chest and worsens breathing.', 'PON 423 · Paediatric Surgery'),
(1, 3, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Reduction of intussusception in a stable child is usually first attempted by:', '["Immediate open surgery in all cases", "Air or contrast enema under imaging", "Oral laxatives", "Abdominal massage at home"]'::jsonb, 1, 'Surgery is needed if this fails or if peritonitis or perforation is present.', 'PON 423 · Paediatric Surgery'),
(1, 4, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Meckel''s diverticulum classically presents in children with:', '["Haematuria", "Painless rectal bleeding", "Projectile vomiting", "Jaundice with pale stools"]'::jsonb, 1, 'Remember the ''rule of 2s'': 2% of people, 2 feet from the ileocaecal valve.', 'PON 423 · Paediatric Surgery'),
(1, 5, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Duodenal atresia is commonly associated with:', '["Down syndrome", "Turner syndrome", "Marfan syndrome", "Cystic fibrosis only"]'::jsonb, 0, 'Check for cardiac defects.', 'PON 423 · Paediatric Surgery'),
(1, 6, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Neonates undergoing surgery are given IV fluids containing glucose mainly because they:', '["Have low glycogen stores and become hypoglycaemic quickly", "Need extra sodium to replace losses from the skin", "Cannot absorb water", "Have high blood sugar"]'::jsonb, 0, 'Monitor blood glucose regularly.', 'PON 423 · Paediatric Surgery'),
(1, 7, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Phimosis in a young boy is:', '["An opening on the underside of the penis", "A swelling of fluid around the testis", "An undescended testis in the groin", "A tight foreskin that cannot be retracted"]'::jsonb, 3, 'It is normal in infants and often resolves.', 'PON 423 · Paediatric Surgery'),
(1, 8, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A testicular torsion in a child needs surgery ideally within:', '["1 month", "48 hours", "2 weeks of the onset of pain", "6 hours of onset of pain"]'::jsonb, 3, 'Delay leads to loss of the testis.', 'PON 423 · Paediatric Surgery'),
(1, 9, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Minimum urine output in an infant after surgery should be about:', '["5 mL/kg/hour as a minimum", "10 mL/kg/hour", "1–2 mL/kg/hour", "0.1 mL/kg/hour"]'::jsonb, 2, 'Adults need at least 0.5 mL/kg/hour.', 'PON 423 · Paediatric Surgery'),
(1, 10, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'The circulating blood volume of a term neonate is about:', '["150 mL/kg", "20 mL/kg", "40 mL/kg (half the adult volume)", "80–90 mL/kg"]'::jsonb, 3, 'A small absolute blood loss is significant in babies.', 'PON 423 · Paediatric Surgery'),
(1, 11, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Hirschsprung-associated enterocolitis presents with:', '["Painless constipation only", "Bloody vomiting only", "Fever, abdominal distension and explosive foul diarrhoea", "Jaundice only, with pale stools and dark urine"]'::jsonb, 2, 'It can be life-threatening; rectal washouts and antibiotics are used.', 'PON 423 · Paediatric Surgery'),
(1, 12, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Neuroblastoma in children arises most commonly from the:', '["Adrenal gland", "Liver", "Kidney", "Bone marrow only"]'::jsonb, 0, 'Raised urine catecholamines help the diagnosis.', 'PON 423 · Paediatric Surgery'),
(1, 13, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A sacrococcygeal teratoma is:', '["A type of hernia", "A tumour at the base of the spine in newborns", "A spinal cord infection", "A blood clot in the sacral veins"]'::jsonb, 1, 'Most are benign at birth, and early removal is advised.', 'PON 423 · Paediatric Surgery'),
(1, 14, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Former premature babies having surgery are at risk of post-operative:', '["Diabetes", "Hypertension only", "Gout and joint pain in the first week", "Apnoea, so they need overnight monitoring"]'::jsonb, 3, 'Risk is highest under 60 weeks post-conceptual age.', 'PON 423 · Paediatric Surgery'),
(1, 15, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'EMLA or other topical anaesthetic cream before cannulation in a child should be applied:', '["24 hours before", "About 60 minutes before, under an occlusive dressing", "1 minute before, with no dressing needed", "After cannulation"]'::jsonb, 1, 'It reduces pain and fear.', 'PON 423 · Paediatric Surgery'),
(1, 16, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Appendicitis in young children is more dangerous than in adults because:', '["It always resolves alone", "It never causes pain in children, so it is found late", "Children cannot have appendicitis", "It perforates earlier and is harder to diagnose"]'::jsonb, 3, 'The omentum is underdeveloped and less able to wall it off.', 'PON 423 · Paediatric Surgery'),
(1, 17, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A ''Gillick competent'' child is one who:', '["Cannot consent at all", "Is always over 18", "Has enough understanding to consent to their own treatment", "Has no parents or guardians to give consent on their behalf"]'::jsonb, 2, 'Competence depends on the child and the decision.', 'PON 423 · Paediatric Surgery'),
(1, 18, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A swallowed button battery stuck in a child''s oesophagus is:', '["Treated with laxatives only", "Removed after a week if it has not passed on its own by then", "An emergency, as it can burn through the oesophagus within hours", "Harmless and passes on its own"]'::jsonb, 2, 'Urgent endoscopic removal is needed.', 'PON 423 · Paediatric Surgery'),
(1, 19, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Malrotation with midgut volvulus in a neonate is suspected with:', '["Constipation without vomiting", "Projectile non-bilious vomiting", "Excess weight gain", "Sudden bilious vomiting"]'::jsonb, 3, 'It is a surgical emergency because the bowel may die.', 'PON 423 · Paediatric Surgery'),
(1, 20, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A child with empyema thoracis may need:', '["Only oral fluids", "Chest drain insertion or thoracoscopic surgery", "No treatment, as empyema always clears with time", "Immediate tracheostomy"]'::jsonb, 1, 'Antibiotics are given as well.', 'PON 423 · Paediatric Surgery'),
(1, 21, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'A long-term effect commonly discussed with men before TURP is:', '["Retrograde ejaculation", "Hearing loss", "Blindness", "Diabetes and weight gain"]'::jsonb, 0, 'Semen passes back into the bladder.', 'PON 423 · Urology'),
(1, 22, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'During TURBT on the lateral bladder wall, sudden leg adduction may occur due to:', '["Obturator nerve stimulation, which risks bladder perforation", "Femoral artery spasm", "Normal muscle reflex with no risk", "Spinal cord injury from the spinal anaesthetic"]'::jsonb, 0, 'An obturator nerve block may be used.', 'PON 423 · Urology'),
(1, 23, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'A common urinary catheter size for an adult is:', '["12–14 Ch (French)", "40 Ch", "24–30 Ch for routine drainage", "4–6 Ch"]'::jsonb, 0, 'Larger three-way catheters (e.g. 20–22 Ch) are used for haematuria and irrigation.', 'PON 423 · Urology'),
(1, 24, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'After kidney transplant, urine output is monitored hourly mainly to detect:', '["Graft dysfunction, rejection or catheter blockage", "Wound healing", "Hypertension only", "Hearing loss from the anti-rejection drugs"]'::jsonb, 0, 'A sudden fall in urine output must be reported.', 'PON 423 · Urology'),
(1, 25, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'A tension-free vaginal tape (TVT) is used to treat:', '["Female stress urinary incontinence", "Kidney stones in the ureter", "Bladder cancer", "Urge incontinence only"]'::jsonb, 0, 'It supports the mid-urethra.', 'PON 423 · Urology'),
(1, 26, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Most ureteric stones smaller than about 5 mm:', '["Need nephrectomy in most cases", "Cause kidney cancer", "Always need open surgery", "Pass on their own with fluids and analgesia"]'::jsonb, 3, 'Tamsulosin may help passage of distal stones.', 'PON 423 · Urology'),
(1, 27, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'A patient s/p TURP has pink-tinged urine and bladder spasms. This is:', '["Indicative of infection", "Normal", "Urinary retention", "Sign of hemorrhage"]'::jsonb, 1, 'Hematuria and spasms are common after TURP.', 'PON 423 · Urology'),
(1, 28, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Acute urinary retention is relieved by:', '["Diuretics to push the urine out", "High fluid intake", "Urethral (or suprapubic) catheterisation", "Antibiotics alone"]'::jsonb, 2, 'Record the residual volume drained.', 'PON 423 · Urology'),
(1, 29, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Squamous cell carcinoma of the bladder in Nigeria is strongly linked to:', '["Smoking only", "Schistosoma haematobium infection", "Hepatitis B infection", "Kidney stones only"]'::jsonb, 1, 'Painless haematuria needs investigation.', 'PON 423 · Urology'),
(1, 30, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Tamsulosin improves urine flow in BPH by:', '["Relaxing smooth muscle in the prostate and bladder neck", "Shrinking the prostate over months", "Killing prostate cells over several months", "Increasing urine production"]'::jsonb, 0, 'Side effects include dizziness and postural hypotension.', 'PON 423 · Urology'),
(1, 31, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'An extraperitoneal bladder rupture after pelvic fracture is usually managed with:', '["Immediate cystectomy", "No treatment, as it always heals", "Oral antibiotics only", "Catheter drainage for about 10–14 days"]'::jsonb, 3, 'Intraperitoneal rupture usually needs surgical repair.', 'PON 423 · Urology'),
(1, 32, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Fournier''s gangrene is:', '["A rapidly spreading necrotising infection of the genital area", "A benign scrotal cyst", "A kidney stone blocking the urethra", "A type of hernia"]'::jsonb, 0, 'It needs urgent debridement and IV antibiotics.', 'PON 423 · Urology'),
(1, 33, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'To reduce catheter-associated urinary tract infection, the drainage bag should be kept:', '["Disconnected often to empty", "On the floor, beside the bed", "Above bladder level", "Below bladder level with a closed system"]'::jsonb, 3, 'Avoid breaking the closed system.', 'PON 423 · Urology'),
(1, 34, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Cystoscopy is usually performed with the patient in the:', '["Prone position with the legs apart", "Lithotomy position", "Sitting position", "Lateral position"]'::jsonb, 1, 'Protect the legs and nerves during positioning.', 'PON 423 · Urology'),
(1, 35, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'A patient with clot retention after prostate surgery needs:', '["Removal of the catheter and discharge", "Diuretics only, to wash the clots out", "Bladder washout to remove clots and continued irrigation", "Oral fluids only"]'::jsonb, 2, 'Use aseptic technique.', 'PON 423 · Urology'),
(1, 36, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'A forgotten ureteric stent left for many months can cause:', '["Better kidney function", "Bladder cure and better kidney function", "No problems at all", "Encrustation, infection and obstruction"]'::jsonb, 3, 'Use a stent register to track removal dates.', 'PON 423 · Urology'),
(1, 37, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'The most common type of kidney stone is:', '["Uric acid", "Struvite", "Cystine", "Calcium oxalate"]'::jsonb, 3, 'High fluid intake helps prevent recurrence.', 'PON 423 · Urology'),
(1, 38, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'After catheterising a patient with chronic retention and a large residual, the nurse should watch for:', '["Constipation and abdominal pain", "Post-obstructive diuresis and haematuria", "Hypoglycaemia", "Hypertension only"]'::jsonb, 1, 'Monitor urine output and electrolytes.', 'PON 423 · Urology'),
(1, 39, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'Finasteride treats benign prostatic hyperplasia by:', '["Increasing testosterone", "Killing bacteria in the prostate gland", "Shrinking the prostate (5-alpha reductase inhibitor)", "Relaxing smooth muscle immediately"]'::jsonb, 2, 'It takes months to work; alpha-blockers act faster.', 'PON 423 · Urology'),
(1, 40, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Urology', 'The classic triad of renal cell carcinoma is:', '["Haematuria, loin pain and a palpable mass", "Headache, vomiting and seizures", "Fever, rash and joint pain", "Cough, weight gain and fatigue"]'::jsonb, 0, 'Most cases are now found by imaging before symptoms.', 'PON 423 · Urology'),
(1, 41, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'An extradural haematoma on CT typically appears as:', '["Blood within the ventricles only", "A crescent-shaped collection across sutures", "A normal brain scan", "A lens-shaped (biconvex) hyperdense collection"]'::jsonb, 3, 'It does not cross skull suture lines.', 'PON 423 · Neurosurgery'),
(1, 42, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Raccoon eyes (periorbital bruising) after head injury suggest:', '["Eye allergy", "Normal bruising from glasses", "Anterior basal skull fracture", "Middle ear infection"]'::jsonb, 2, 'Avoid nasal tubes in these patients.', 'PON 423 · Neurosurgery'),
(1, 43, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'An arteriovenous malformation (AVM) of the brain may present with:', '["Hearing loss only", "Painless jaundice", "Haemorrhage or seizures in a young person", "Leg ulcers"]'::jsonb, 2, 'Treatment includes surgery, embolisation or radiosurgery.', 'PON 423 · Neurosurgery'),
(1, 44, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Dexamethasone reduces symptoms in brain tumours by:', '["Increasing CSF production", "Killing tumour cells immediately", "Lowering blood pressure", "Reducing vasogenic oedema around the tumour"]'::jsonb, 3, 'Monitor blood glucose.', 'PON 423 · Neurosurgery'),
(1, 45, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A burr hole in an emergency extradural haematoma is done to:', '["Insert a feeding tube", "Take a brain biopsy only", "Release the blood and relieve brain compression", "Measure blood glucose"]'::jsonb, 2, 'Definitive craniotomy usually follows.', 'PON 423 · Neurosurgery'),
(1, 46, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'An external ventricular drain (EVD) must be clamped:', '["Before moving or repositioning the patient", "When CSF drainage is low", "Never at any time", "Only at night"]'::jsonb, 0, 'Uncontrolled drainage can cause brain collapse or bleeding.', 'PON 423 · Neurosurgery'),
(1, 47, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient after posterior fossa surgery should be watched especially for:', '["Hair loss", "Hand rash", "Breathing problems and swallowing difficulty", "Knee pain"]'::jsonb, 2, 'The brainstem and lower cranial nerves are near the surgery site.', 'PON 423 · Neurosurgery'),
(1, 48, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A lumbar drain for CSF leak is managed by:', '["Lowering it to the floor", "Draining as much as possible", "Clamping it permanently", "Draining at the prescribed rate and keeping the drain at the set level"]'::jsonb, 3, 'Over-drainage can cause headache and brain herniation.', 'PON 423 · Neurosurgery'),
(1, 49, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Blood-stained CSF that becomes more red in an EVD after surgery should be:', '["Reported immediately as possible new bleeding", "Expected and ignored", "Treated by raising the drain", "Recorded once a day only"]'::jsonb, 0, 'Also note the volume drained each hour.', 'PON 423 · Neurosurgery'),
(1, 50, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Glioblastoma is:', '["A highly malignant primary brain tumour", "A type of blood clot", "A bone fracture", "A benign skin tumour"]'::jsonb, 0, 'Treatment includes surgery, radiotherapy and chemotherapy.', 'PON 423 · Neurosurgery'),
(1, 51, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'In acute spinal cord injury, the nurse prevents pressure ulcers by:', '["Leaving the patient in one position", "Sitting the patient up quickly", "Using tight straps", "Log rolling every 2–3 hours on a pressure-relieving surface"]'::jsonb, 3, 'Sensation is absent below the injury.', 'PON 423 · Neurosurgery'),
(1, 52, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Coma (head injury) is classified as severe when the Glasgow Coma Scale is:', '["≤12", "≤14", "≤8", "≤10"]'::jsonb, 2, 'GCS ≤8 means severe brain injury/coma, and usually that the airway needs protecting (intubation).', 'PON 423 · Neurosurgery'),
(1, 53, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Refer to Q#19, the patient had undergone through craniotomy. Bleeding was notified on CT scan after one week of surgery which is known as;', '["Reactionary Hemorrhage", "Primary Hemorrhage", "Secondary Hemorrhage", "Venous Hemorrhage"]'::jsonb, 2, 'Bleeding appearing a week after surgery is delayed — secondary haemorrhage, usually from infection.', 'PON 423 · Neurosurgery'),
(1, 54, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'After lumbar laminectomy, the nurse checks:', '["Leg movement, sensation and bladder function", "Eye movement only", "Swallowing only", "Hearing only"]'::jsonb, 0, 'New weakness may indicate a haematoma compressing the nerves.', 'PON 423 · Neurosurgery'),
(1, 55, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with a head injury has a GCS of 7. The priority is:', '["Waiting for 24 hours", "Securing the airway, often by intubation", "Sitting the patient up to eat", "Giving oral fluids"]'::jsonb, 1, 'A GCS of 8 or less means the airway may not be protected.', 'PON 423 · Neurosurgery'),
(1, 56, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'The most common trigger for autonomic dysreflexia in a patient with chronic spinal cord injury is', '["cold room temperature", "a distended bladder or bowel", "mild anxiety", "reading a book"]'::jsonb, 1, 'Bladder distention (e.g., from a blocked catheter) and bowel impaction are the most common noxious stimuli that trigger autonomic dysreflexia in patients with SCI at or above T6.', 'PON 423 · Neurosurgery'),
(1, 57, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Clear watery nasal discharge after transsphenoidal surgery should be tested for:', '["Bilirubin", "Haemoglobin", "Glucose or beta-2 transferrin to detect CSF", "Potassium"]'::jsonb, 2, 'A CSF leak raises the risk of meningitis.', 'PON 423 · Neurosurgery'),
(1, 58, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A decompressive craniectomy involves:', '["Closing the scalp only", "Draining CSF from the spine", "Replacing the skull with metal immediately", "Removing a large piece of skull to allow the swollen brain to expand"]'::jsonb, 3, 'The bone flap may be stored and replaced later.', 'PON 423 · Neurosurgery'),
(1, 59, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Transsphenoidal pituitary surgery patients are told after surgery to avoid:', '["Drinking water", "Blowing the nose, sneezing hard and straining", "Sitting up", "Walking"]'::jsonb, 1, 'These raise pressure and may cause CSF leak.', 'PON 423 · Neurosurgery'),
(1, 60, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with a chronic spinal cord injury at T4 develops a sudden pounding headache, severe hypertension, profuse sweating and flushing above the injury level, and bradycardia after their urinary catheter becomes blocked. This presentation is most consistent with', '["Cushing''s triad from raised intracranial pressure", "a simple tension headache", "spinal shock", "autonomic dysreflexia"]'::jsonb, 3, 'Autonomic dysreflexia occurs in patients with SCI at or above T6, triggered by a noxious stimulus below the injury level (commonly bladder distention); it causes an unopposed sympathetic surge below the lesion, producing severe hypertension, reflex bradycardia, and flushing/sweating above the lesion, and is a medical emergency.', 'PON 423 · Neurosurgery'),
(1, 61, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A paradoxical pulse occurs in a client who had a coronary artery bypass graft (CABG) surgery two (2) days ago. Which of the following surgical complications should the nurse suspect?', '["Left-sided heart failure", "Pericardial tamponade", "Complete heart block", "Aortic regurgitation"]'::jsonb, 1, 'Pulsus paradoxus (systolic fall over 10 mmHg on inspiration) after cardiac surgery suggests cardiac tamponade.', 'PON 423 · Cardiothoracic Surgery'),
(1, 62, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Thoracostomy differs from thoracotomy in that it is:', '["A large incision for major intrathoracic surgery", "Only used for cardiac surgery", "A small opening for placing a chest drain", "Identical to thoracotomy"]'::jsonb, 2, 'Thoracostomy is a much smaller procedure aimed specifically at inserting a drainage tube, not full surgical access.', 'PON 423 · Cardiothoracic Surgery'),
(1, 63, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Chest tube drainage exceeding approximately 200–300mL per hour after coronary artery bypass surgery should prompt concern for:', '["Resolution of the surgical procedure", "Postoperative haemorrhage requiring urgent evaluation", "Normal expected postoperative drainage", "Chest tube malfunction only, with no clinical significance"]'::jsonb, 1, 'Chest tube output consistently exceeding roughly 200–300mL/hour (or specific institutional thresholds) after cardiac surgery raises concern for significant postoperative bleeding and may require surgical re-exploration.', 'PON 423 · Cardiothoracic Surgery'),
(1, 64, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Mitral valve replacement with a mechanical valve requires an INR target of about:', '["5.0–6.0", "1.0–1.5", "2.5–3.5", "0.5–1.0"]'::jsonb, 2, 'Targets vary with valve type and position.', 'PON 423 · Cardiothoracic Surgery'),
(1, 65, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After a pneumonectomy, the trachea characteristically shifts:', '["Away from the operated side", "Never shifts after pneumonectomy", "Shifts downward only", "Toward the operated (empty) side"]'::jsonb, 3, 'Unlike tension pneumothorax, the empty space left after removing a whole lung pulls the trachea toward that side over time.', 'PON 423 · Cardiothoracic Surgery'),
(1, 66, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'The most common cardiac irregularity seen after thoracotomy, especially in patients over 50, is:', '["Complete heart block", "Atrial fibrillation", "Ventricular fibrillation", "Sinus bradycardia"]'::jsonb, 1, 'Surgical manipulation near the heart commonly triggers AF in older patients.', 'PON 423 · Cardiothoracic Surgery'),
(1, 67, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Median sternotomy is the standard approach for:', '["Lung lobectomy", "Splenectomy", "Open heart surgery", "Oesophagectomy"]'::jsonb, 2, 'Splitting the sternum gives direct access to the heart.', 'PON 423 · Cardiothoracic Surgery'),
(1, 68, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A sudden drop in blood pressure with raised CVP and narrow pulse pressure after cardiac surgery suggests:', '["Normal recovery", "Hypertension", "Hypovolaemia only", "Cardiac tamponade"]'::jsonb, 3, 'Urgent surgical review is needed.', 'PON 423 · Cardiothoracic Surgery'),
(1, 69, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Before cardiac surgery, the patient is taught deep breathing and coughing with:', '["No support", "Chest support using a pillow", "Breath holding for 2 minutes", "Arms raised above the head"]'::jsonb, 1, 'Splinting reduces pain on coughing.', 'PON 423 · Cardiothoracic Surgery'),
(1, 70, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Following lobectomy, the patient is positioned and mobilised to:', '["Prevent eating", "Encourage lung expansion and drainage", "Avoid all coughing", "Keep the remaining lung collapsed"]'::jsonb, 1, 'Early physiotherapy is important.', 'PON 423 · Cardiothoracic Surgery'),
(1, 71, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After cardiac surgery, the chest drain output should be reported immediately if it exceeds about:', '["20 mL per hour", "5 mL per hour", "200 mL per hour for 2 consecutive hours", "50 mL per day"]'::jsonb, 2, 'Also monitor for tamponade if drainage suddenly stops.', 'PON 423 · Cardiothoracic Surgery'),
(1, 72, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Sternal precautions after median sternotomy include:', '["Avoiding pushing, pulling or lifting heavy objects for about 6–8 weeks", "Doing press-ups from day 1", "Lifting heavy weights to strengthen the chest", "Sleeping only prone"]'::jsonb, 0, 'This allows the sternum to heal.', 'PON 423 · Cardiothoracic Surgery'),
(1, 73, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After CABG using the saphenous vein, the leg wound should be monitored for:', '["Visual changes", "Hair growth", "Infection, bleeding and swelling", "Hearing loss"]'::jsonb, 2, 'Elevate the leg and use compression as advised.', 'PON 423 · Cardiothoracic Surgery'),
(1, 74, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A side effect of protamine given after bypass is:', '["Bradycardia only from vagal effect", "Hypertension only", "Hypotension and possible anaphylaxis", "Hyperglycaemia"]'::jsonb, 2, 'Give it slowly.', 'PON 423 · Cardiothoracic Surgery'),
(1, 75, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Following thoracic surgery, incentive spirometry helps to:', '["Prevent atelectasis and pneumonia", "Stop chest drain output", "Lower blood pressure", "Prevent DVT directly"]'::jsonb, 0, 'Encourage use about 10 times an hour while awake.', 'PON 423 · Cardiothoracic Surgery'),
(1, 76, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'The nurse is preparing to remove a chest tube. Before the removal, the nurse should instruct the patient to perform which of the following?', '["To exhale and bear down (Valsalva maneuver)", "To hold their breath and cough forcefully", "To perform deep breaths", "To breathe normally and shallowly"]'::jsonb, 0, 'The Valsalva maneuver, which involves exhaling and bearing down, increases intrathoracic pressure. This helps to prevent air from being sucked into the chest cavity as the tube is being removed.', 'PON 423 · Cardiothoracic Surgery'),
(1, 77, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'The main treatment priority for a flail chest is:', '["Strapping the chest tightly", "Restricting oxygen", "Immediate surgery for all patients", "Good analgesia and support of breathing"]'::jsonb, 3, 'Epidural or regional blocks help breathing and coughing.', 'PON 423 · Cardiothoracic Surgery'),
(1, 78, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'During cardiopulmonary bypass, heparin is given to:', '["Stop the heart", "Reduce blood pressure", "Prevent infection", "Prevent clotting in the bypass circuit"]'::jsonb, 3, 'Protamine reverses heparin at the end.', 'PON 423 · Cardiothoracic Surgery'),
(1, 79, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A nurse is preparing to ambulate a patient with a chest tube and a UWSD. The nurse should:', '["Disconnect the UWSD system from the suction", "Ensure the UWSD system remains upright and below the chest level", "Disconnect the chest tube from the UWSD system", "Clamp the chest tube for the duration of the walk"]'::jsonb, 1, 'The UWSD system must remain upright to maintain the water seal and below the patient''s chest to use gravity for drainage. Clamping or disconnecting the system is unsafe and should not be done during ambulation.', 'PON 423 · Cardiothoracic Surgery'),
(1, 80, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'The chest tube placed high and posterior or lateral to drain', '["Blood", "Air", "Pleural fluids", "Fluid"]'::jsonb, 1, 'A chest tube placed high/anterior is positioned to drain air.', 'PON 423 · Cardiothoracic Surgery'),
(1, 81, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient with circumferential full-thickness burns to the chest has difficulty breathing. The nurse anticipates:', '["Chest tube insertion", "Escharotomy", "Fasciotomy", "Bronchoscopy"]'::jsonb, 1, 'Circumferential eschar restricts chest expansion; escharotomy relieves pressure.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 82, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A tissue expander is gradually filled with:', '["Saline through a port", "Antibiotic cream", "Blood", "Air"]'::jsonb, 0, 'It stretches the skin for later reconstruction.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 83, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Pressure garments for burn scars are usually worn for:', '["Around 23 hours a day for many months", "One hour a day", "Only during sport", "Only at night for a week"]'::jsonb, 0, 'They reduce hypertrophic scarring.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 84, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Early excision and grafting of deep burns aims to:', '["Delay healing", "Avoid the need for fluids", "Reduce infection and speed healing", "Increase scarring"]'::jsonb, 2, 'It is usually done within the first days after the burn.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 85, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Wound care in major burns is typically initiated within:', '["1 week", "24–72 hours", "1–2 hours", "1 month"]'::jsonb, 1, 'Wound care begins once the patient is stabilised from the initial resuscitation phase, generally within this window.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 86, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The correct first aid for a chemical burn is:', '["Copious irrigation with water", "Cover with a dry dressing only", "Apply a neutralising agent immediately", "Apply ice directly"]'::jsonb, 0, 'Water dilutes and washes away the chemical; neutralisers generate extra heat and worsen the burn.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 87, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Lymphoedema surgery (e.g. lymphatic bypass) is considered when:', '["The patient has a sprained ankle", "The leg is normal", "Swelling is mild and recent", "Conservative treatment such as compression fails"]'::jsonb, 3, 'Compression and skin care remain important.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 88, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'After a split-thickness skin graft, the graft site is usually first inspected at about:', '["Day 30", "Day 5", "Day 1 every hour", "After 6 months"]'::jsonb, 1, 'Early disturbance may dislodge the graft.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 89, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A full-thickness skin graft donor site is usually:', '["Treated with laser", "Covered with another graft", "Left open to heal alone", "Closed directly with sutures"]'::jsonb, 3, 'Common sites are behind the ear and the groin.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 90, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'For small or patchy burns, a quick estimate of surface area can be made using:', '["No estimation method exists", "The Rule of Nines only", "The patient''s own palm ≈ 1% TBSA", "Lund and Browder chart only in adults"]'::jsonb, 2, 'The palm method is a convenient bedside estimate: the patient''s own palm (including fingers) is roughly equal to 1% of their total body surface area.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 91, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Silver-containing dressings on wounds help mainly by:', '["Cooling the wound", "Making the wound dry and cracked", "Reducing bacterial load", "Increasing bleeding"]'::jsonb, 2, 'They are used in burns and infected wounds.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 92, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Flap observations after surgery typically include colour, temperature, capillary refill and:', '["Turgor (tension) and Doppler signal", "Pupil size", "Hearing", "Hair growth"]'::jsonb, 0, 'Observations are frequent in the first 24–48 hours.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 93, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient with facial burns and singed nasal hairs is at risk for:', '["Airway obstruction", "Hypokalemia", "Hyperglycemia", "Hypothermia"]'::jsonb, 0, 'Singed nasal hairs suggest inhalation injury, which can cause airway edema.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 94, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Medicinal leeches may be used on a congested flap to:', '["Glue the wound", "Supply arterial blood", "Stop infection", "Remove venous blood and improve outflow"]'::jsonb, 3, 'Prophylactic antibiotics are given against Aeromonas.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 95, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient sustains a chemical burn from a strong acid. The immediate first-aid priority is to:', '["Apply a neutralising alkaline agent directly to the burn", "Apply ice directly to the burn", "Irrigate copiously with water, avoiding neutralising agents which can generate additional heat/injury", "Cover the wound tightly with an occlusive dressing immediately with no irrigation"]'::jsonb, 2, 'Chemical burns should be irrigated copiously with water — neutralising agents are avoided as the chemical reaction can generate additional heat and worsen tissue injury.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 96, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Abdominoplasty patients are positioned after surgery:', '["Standing upright", "Flat with legs straight", "Prone", "With hips and knees slightly flexed to reduce wound tension"]'::jsonb, 3, 'Early walking with a bent posture is common.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 97, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The Waterlow and Braden scales are used to:', '["Assess pressure ulcer risk", "Score pain", "Grade skin grafts", "Measure burn depth"]'::jsonb, 0, 'Act on the score with prevention measures.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 98, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Systemic burn shock risk begins above what %TBSA?', '[">50%", ">5%", ">20%", ">10%"]'::jsonb, 2, 'Beyond 20% TBSA, inflammation becomes whole-body rather than local.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 99, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The basal metabolic rate (BMR) in a major burns patient can increase by:', '["100–200%", "No change", "10–20%", "500–600%"]'::jsonb, 0, 'The body''s energy demands roughly double or triple after a major burn, driving the hypermetabolic state that must be matched with adequate nutrition.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 100, 'Perioperative Mock — Day 6 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Skin graft donor sites are usually covered with:', '["Nothing", "A non-adherent or alginate dressing left in place as advised", "Tight plastic wrap changed hourly", "Alcohol swabs"]'::jsonb, 1, 'Donor sites often heal in 10–14 days.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(2, 1, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Facial wounds have a good blood supply, so they:', '["Must not be cleaned", "Heal well and can often be closed later than other wounds", "Never heal well and always need skin grafts", "Always become infected"]'::jsonb, 1, 'Careful alignment of the lip border is important.', 'PON 417 · Maxillofacial Surgery'),
(2, 2, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A patient with intermaxillary fixation who feels sick should be:', '["Given a large meal", "Given antiemetics early, with cutters ready if vomiting occurs", "Left alone in a side room until the nausea passes", "Encouraged to vomit through the wires"]'::jsonb, 1, 'Vomiting with wired jaws risks aspiration.', 'PON 417 · Maxillofacial Surgery'),
(2, 3, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The cleft lip and palate team usually includes the surgeon, orthodontist, speech therapist and:', '["Ophthalmologist only", "Specialist nurse and audiologist", "Orthopaedic surgeon only", "Cardiologist only"]'::jsonb, 1, 'Care continues from birth to adulthood.', 'PON 417 · Maxillofacial Surgery'),
(2, 4, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Numbness of the cheek and upper lip after a zygomatic fracture is due to injury of the:', '["Hypoglossal nerve", "Vagus nerve", "Facial nerve", "Infraorbital nerve"]'::jsonb, 3, 'It runs through the orbital floor.', 'PON 417 · Maxillofacial Surgery'),
(2, 5, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A ''dish face'' appearance after facial trauma suggests:', '["A simple nasal fracture", "A mandible fracture only", "A Le Fort fracture with the midface pushed back", "A dental abscess"]'::jsonb, 2, 'Look for malocclusion and mobile maxilla.', 'PON 417 · Maxillofacial Surgery'),
(2, 6, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The main risk of a maxillary sinus opening after upper molar extraction is:', '["Hearing loss on that side", "An oro-antral fistula", "Facial palsy", "Mandible fracture"]'::jsonb, 1, 'Patients should avoid nose blowing.', 'PON 417 · Maxillofacial Surgery'),
(2, 7, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A septal haematoma after nasal trauma must be drained urgently because it can cause:', '["Hearing loss", "Blindness on the same side", "Cartilage necrosis and saddle nose deformity", "Facial palsy"]'::jsonb, 2, 'Infection can also spread.', 'PON 417 · Maxillofacial Surgery'),
(2, 8, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A bilateral mandibular fracture in an unconscious patient can cause airway obstruction because:', '["The tongue loses support and falls back", "The larynx is crushed", "The teeth fall into the trachea in all cases", "The nose becomes blocked"]'::jsonb, 0, 'Pull the tongue or mandible forward and protect the airway.', 'PON 417 · Maxillofacial Surgery'),
(2, 9, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Tooth avulsion (knocked-out permanent tooth) is best managed by:', '["Scrubbing the root and drying it", "Storing it dry in tissue", "Replanting it quickly or storing it in milk", "Throwing it away and fitting a denture later"]'::jsonb, 2, 'Handle by the crown, not the root.', 'PON 417 · Maxillofacial Surgery'),
(2, 10, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The most common benign salivary gland tumour is:', '["Pleomorphic adenoma", "Mucoepidermoid carcinoma", "Ameloblastoma", "Warthin''s tumour only"]'::jsonb, 0, 'It usually occurs in the parotid gland.', 'PON 417 · Maxillofacial Surgery'),
(2, 11, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'After cleft lip repair, the nurse should feed the baby:', '["Only adult food from a spoon", "With a hard dummy", "As advised, often by cup, spoon or special bottle", "Nothing for 2 weeks"]'::jsonb, 2, 'Protect the lip suture line.', 'PON 417 · Maxillofacial Surgery'),
(2, 12, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Bisphosphonate use is linked to:', '["Cleft palate in the patient''s children", "Dental caries only", "Improved jaw healing in all cases", "Medication-related osteonecrosis of the jaw"]'::jsonb, 3, 'Check drug history before dental surgery.', 'PON 417 · Maxillofacial Surgery'),
(2, 13, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Oral hygiene after jaw surgery commonly uses:', '["Hard toothbrush and abrasive paste", "Chlorhexidine mouthwash and a soft toothbrush", "No mouth care until the wires are removed", "Alcohol spirits"]'::jsonb, 1, 'Good hygiene reduces wound infection.', 'PON 417 · Maxillofacial Surgery'),
(2, 14, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A cleft palate in a baby causes problems mainly with:', '["Vision", "Feeding and speech", "Hearing only in adults", "Walking"]'::jsonb, 1, 'Special bottles or feeding techniques are used.', 'PON 417 · Maxillofacial Surgery'),
(2, 15, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A dental chart (odontogram) in maxillofacial surgery is used to:', '["Record pain scores and analgesia only", "Record fluid balance", "Record teeth present, missing or damaged", "Record blood pressure"]'::jsonb, 2, 'It supports planning and legal records.', 'PON 417 · Maxillofacial Surgery'),
(2, 16, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Shoulder drop after radical neck dissection is caused by injury to the:', '["Facial nerve", "Optic nerve", "Radial nerve", "Spinal accessory nerve"]'::jsonb, 3, 'It supplies the trapezius muscle.', 'PON 417 · Maxillofacial Surgery'),
(2, 17, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Open reduction and internal fixation of the mandible commonly uses:', '["Titanium miniplates and screws", "Elastic bandages only", "External skin traction", "Plaster of Paris around the jaw"]'::jsonb, 0, 'They allow earlier jaw movement than wiring alone.', 'PON 417 · Maxillofacial Surgery'),
(2, 18, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A child with noma (cancrum oris) needs:', '["Only eye drops", "No treatment, as it heals without help", "Only dental fillings", "Nutritional support, antibiotics and later reconstruction"]'::jsonb, 3, 'It is linked to malnutrition and poor oral hygiene.', 'PON 417 · Maxillofacial Surgery'),
(2, 19, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Before maxillofacial surgery, the throat pack is placed mainly to:', '["Reduce pain after the operation", "Prevent blood and debris entering the airway or stomach", "Keep the patient warm", "Prevent infection"]'::jsonb, 1, 'Its removal must be checked and documented.', 'PON 417 · Maxillofacial Surgery'),
(2, 20, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A nasal fracture is best assessed for reduction after:', '["Within 1 minute", "About 2 years later", "About 5–10 days, when swelling has settled", "6 months"]'::jsonb, 2, 'A septal haematoma must be drained urgently.', 'PON 417 · Maxillofacial Surgery'),
(2, 21, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Tropicamide drops are used before eye examination to:', '["Constrict the pupil", "Treat infection", "Lower eye pressure", "Dilate the pupil"]'::jsonb, 3, 'Patients should not drive until vision returns to normal.', 'PON 417 · Ophthalmic Surgery'),
(2, 22, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Angle-closure glaucoma attacks may be triggered by:', '["Dim light or dilating drugs", "Drinking water", "Sleeping well in a bright room", "Bright sunlight"]'::jsonb, 0, 'The pupil dilates and blocks drainage of fluid.', 'PON 417 · Ophthalmic Surgery'),
(2, 23, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A dendritic corneal ulcer is caused by:', '["Herpes simplex virus", "Fungi only", "Allergy to pollen", "Bacteria only"]'::jsonb, 0, 'Steroid drops should not be used alone; antiviral treatment is needed.', 'PON 417 · Ophthalmic Surgery'),
(2, 24, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Allergic conjunctivitis is typically treated with:', '["Atropine drops", "Eye patching for a week", "Antihistamine or mast-cell stabiliser drops", "Antibiotic surgery"]'::jsonb, 2, 'Itching is the main symptom.', 'PON 417 · Ophthalmic Surgery'),
(2, 25, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'An artificial eye (prosthesis) socket should be:', '["Kept dry and uncovered", "Cleaned regularly and checked for discharge", "Never cleaned, so the socket is not disturbed", "Rinsed with alcohol"]'::jsonb, 1, 'Teach the patient how to remove and insert the prosthesis.', 'PON 417 · Ophthalmic Surgery'),
(2, 26, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A foreign body on the cornea is removed:', '["By rubbing the eye hard with a dry towel", "Without anaesthetic using fingers", "With tweezers deep into the eye", "After local anaesthetic drops, using a sterile needle or cotton bud"]'::jsonb, 3, 'Use fluorescein to check for abrasions afterwards.', 'PON 417 · Ophthalmic Surgery'),
(2, 27, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Intravitreal injection of anti-VEGF drugs is used for:', '["Conjunctivitis", "Wet age-related macular degeneration and diabetic macular oedema", "Squint and lazy eye in children", "Cataract"]'::jsonb, 1, 'The procedure is done under aseptic conditions.', 'PON 417 · Ophthalmic Surgery'),
(2, 28, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A cataract in an infant needs early surgery because:', '["It cures itself by school age", "It causes deafness", "It spreads to the other eye", "Untreated, it causes permanent amblyopia"]'::jsonb, 3, 'The visual system develops in early childhood.', 'PON 417 · Ophthalmic Surgery'),
(2, 29, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A child with retinoblastoma may present with:', '["A white pupil reflex (leukocoria) in photographs", "Squint only in adults", "A red eye only", "Hearing loss on the same side"]'::jsonb, 0, 'It is a cancer of the retina in young children.', 'PON 417 · Ophthalmic Surgery'),
(2, 30, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Enucleation means:', '["Removal of the eyelid", "Removal of the lens", "Repair of the retina", "Removal of the whole eyeball"]'::jsonb, 3, 'Evisceration removes the contents but leaves the sclera.', 'PON 417 · Ophthalmic Surgery'),
(2, 31, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Ophthalmia neonatorum is:', '["Conjunctivitis in a newborn within the first month", "Squint in teenagers", "Cataract in adults over 60", "Glaucoma in the elderly"]'::jsonb, 0, 'Gonococcal and chlamydial infection are important causes.', 'PON 417 · Ophthalmic Surgery'),
(2, 32, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'During eye surgery under local anaesthesia, the patient should be told to:', '["Move the head to help the surgeon", "Keep the head still and tell staff if they need to move or cough", "Sit up halfway through", "Talk throughout, so the team knows they are comfortable"]'::jsonb, 1, 'Explain before draping covers the face.', 'PON 417 · Ophthalmic Surgery'),
(2, 33, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A patient with endophthalmitis needs:', '["Steroid cream on the eyelids only", "Urgent intravitreal antibiotics", "Eye drops only after a week", "Eye exercises"]'::jsonb, 1, 'Vision can be lost within hours.', 'PON 417 · Ophthalmic Surgery'),
(2, 34, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Dacryocystorhinostomy (DCR) is done to treat:', '["Blocked nasolacrimal duct", "Retinal detachment", "Open-angle glaucoma", "Cataract"]'::jsonb, 0, 'It creates a new drainage path from the lacrimal sac to the nose.', 'PON 417 · Ophthalmic Surgery'),
(2, 35, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Acetazolamide is used in acute glaucoma to:', '["Dilate the pupil", "Stop bleeding inside the eye", "Reduce aqueous humour production", "Treat infection"]'::jsonb, 2, 'It is a carbonic anhydrase inhibitor.', 'PON 417 · Ophthalmic Surgery'),
(2, 36, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Oxygen given under eye drapes during surgery with cautery increases the risk of:', '["Fire", "Hypertension", "Infection", "Hypothermia"]'::jsonb, 0, 'Use the lowest oxygen needed and allow it to clear.', 'PON 417 · Ophthalmic Surgery'),
(2, 37, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A ''curtain'' coming down over the vision suggests:', '["Retinal detachment", "Dry eye", "Cataract", "Allergic conjunctivitis"]'::jsonb, 0, 'Urgent referral is needed.', 'PON 417 · Ophthalmic Surgery'),
(2, 38, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Corneal transplant (keratoplasty) rejection may present with:', '["Hearing loss and dizziness", "Redness, pain, light sensitivity and reduced vision", "No symptoms ever", "Better vision"]'::jsonb, 1, 'Remember ''RSVP'': Redness, Sensitivity, Vision loss, Pain.', 'PON 417 · Ophthalmic Surgery'),
(2, 39, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Laser refractive surgery (e.g. LASIK) reshapes the:', '["Lens", "Retina", "Iris", "Cornea"]'::jsonb, 3, 'It corrects myopia, hyperopia and astigmatism.', 'PON 417 · Ophthalmic Surgery'),
(2, 40, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Vitamin A deficiency in children can cause:', '["Cataract in both eyes", "Glaucoma", "Night blindness and xerophthalmia", "Myopia only"]'::jsonb, 2, 'Vitamin A supplementation prevents blindness.', 'PON 417 · Ophthalmic Surgery'),
(2, 41, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Acute mastoiditis in a child presents with:', '["Nasal bleeding only", "A painless neck lump", "Hearing improvement and a dry ear", "Swelling and redness behind the ear with the ear pushed forward"]'::jsonb, 3, 'It needs IV antibiotics and possibly surgery.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 42, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Vocal cord nodules are most common in:', '["People who never speak", "People who overuse their voice, e.g. teachers and singers", "Smokers only", "Newborns and infants"]'::jsonb, 1, 'Speech therapy is the main treatment.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 43, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A sudden sensorineural hearing loss should be treated:', '["Urgently, often with steroids within days", "With grommets after 6 months", "With ear syringing", "After 6 months"]'::jsonb, 0, 'Early treatment improves recovery.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 44, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A laryngectomy stoma should be protected with:', '["A stoma cover or bib to filter and humidify air", "Tight plastic wrap", "Nothing at all, leaving it open", "Cotton wool pushed into the stoma"]'::jsonb, 0, 'Water must never enter the stoma.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 45, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Juvenile nasopharyngeal angiofibroma is:', '["A common cold", "A vascular tumour in adolescent boys causing heavy nosebleeds", "A fungal infection", "A type of tonsillitis"]'::jsonb, 1, 'Embolisation before surgery reduces bleeding.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 46, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A patient after FESS is advised to avoid:', '["Walking and light activity", "Sleeping", "Nose blowing and heavy lifting for about a week", "Drinking water"]'::jsonb, 2, 'Saline nasal douching helps healing.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 47, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Subcutaneous emphysema around a new tracheostomy suggests:', '["Normal healing of the stoma", "Infection only", "Air leaking into the tissues", "Low blood sugar"]'::jsonb, 2, 'Report and check tube position.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 48, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'The suction catheter for a tracheostomy should be no more than:', '["Half the internal diameter of the tube", "Twice the diameter of the tube", "Any size that is available", "The same diameter as the tube"]'::jsonb, 0, 'Larger catheters cause hypoxia and trauma.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 49, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A cochlear implant is used for:', '["Chronic sinusitis", "Tonsillitis", "Conductive hearing loss from wax", "Severe to profound sensorineural hearing loss"]'::jsonb, 3, 'It stimulates the auditory nerve directly.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 50, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Adenoidectomy is performed mainly for:', '["Hearing loss in the elderly", "Thyroid swelling", "Nasal obstruction, snoring and glue ear in children", "Dental caries and gum disease"]'::jsonb, 2, 'It is often combined with tonsillectomy or grommets.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 51, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Suctioning a tracheostomy should last no longer than about:', '["About 1 hour", "10–15 seconds per pass", "Only 1 second", "2 minutes"]'::jsonb, 1, 'Pre-oxygenate and use the correct catheter size.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 52, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After total laryngectomy, the patient cannot:', '["Breathe through the nose or mouth", "Hear", "Swallow at all", "Smell anything ever, even with help"]'::jsonb, 0, 'The trachea is brought out as a permanent stoma.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 53, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Nasopharyngeal carcinoma may present with:', '["Leg swelling", "Unilateral glue ear, nasal blockage and neck lumps", "Hand weakness", "Chest pain and cough"]'::jsonb, 1, 'Unilateral middle ear effusion in an adult needs nasopharynx examination.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 54, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'During a tracheostomy emergency, a patient with a laryngectomy is given oxygen:', '["Through the mouth and nose only", "Through the neck stoma, not the face", "By nasal cannula", "Not at all"]'::jsonb, 1, 'There is no connection between the mouth and trachea.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 55, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Tonsillectomy is commonly indicated for:', '["Recurrent tonsillitis and obstructive sleep apnoea", "Nosebleeds", "Ear wax and itching", "A single sore throat"]'::jsonb, 0, 'Typical criteria include several episodes per year.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 56, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After stapedectomy, the patient is told that hearing may:', '["Be reduced at first because of packing and swelling", "Return to perfect immediately", "Be lost in the other ear", "Never change at all"]'::jsonb, 0, 'Sudden severe dizziness should be reported.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 57, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After tonsillectomy, patients are encouraged to:', '["Avoid all food for a week", "Drink only very hot drinks", "Avoid painkillers and eating", "Eat normal food and drink well to keep the throat clean"]'::jsonb, 3, 'Regular analgesia helps eating.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 58, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A thyroidectomy patient with bilateral recurrent laryngeal nerve injury may present with:', '["Loud clear voice", "Hearing loss", "Eye pain and blurred vision", "Stridor and respiratory distress"]'::jsonb, 3, 'This may need reintubation or tracheostomy.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 59, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A child after grommet insertion is usually advised to:', '["Never bathe again", "Swim deep underwater daily", "Avoid dirty water entering the ears", "Avoid all school for a month"]'::jsonb, 2, 'Grommets usually fall out on their own after months.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 60, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Glue ear (otitis media with effusion) in children mainly causes:', '["Leg weakness", "Conductive hearing loss", "Facial palsy", "Blindness"]'::jsonb, 1, 'It may affect speech and school performance.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 61, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The three main principles of radiation protection are:', '["Cost, staff and space", "Speed, noise and light", "Heat, cold and water", "Time, distance and shielding"]'::jsonb, 3, 'Minimise time, maximise distance and use shielding.', 'Radiology & Radiation Safety'),
(2, 62, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Using ultrasound guidance for central line insertion primarily helps to:', '["Eliminate the need for sterile technique", "Visualise the vein in real time and reduce mechanical complications", "Replace the need for a post-procedure chest X-ray in all cases", "Increase radiation exposure"]'::jsonb, 1, 'Real-time ultrasound guidance allows direct visualisation of the target vein and needle tip, reducing complications such as arterial puncture, pneumothorax, and failed cannulation attempts.', 'Radiology & Radiation Safety'),
(2, 63, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Ionic (High Osmolar) contrast media, compared to non-ionic (Low Osmolar) contrast media, are associated with:', '["Identical side-effect profile and cost", "No side effects at any dose", "More side effects but lower cost", "Fewer side effects and higher cost"]'::jsonb, 2, 'Ionic/HOCM agents dissociate into ions, have high osmolality, and cause more reactions, but are cheaper than non-ionic/LOCM agents such as iohexol.', 'Radiology & Radiation Safety'),
(2, 64, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Which contrast media type is preferred in high-risk patients such as those with renal failure, cardiac failure, or diabetes mellitus?', '["Barium sulfate only", "Non-ionic (Low Osmolar) contrast media", "No contrast is ever needed in high-risk patients", "Ionic (High Osmolar) contrast media"]'::jsonb, 1, 'Non-ionic/Low Osmolar Contrast Media (LOCM) cause fewer reactions and are preferred in high-risk groups including renal failure, cardiac failure, diabetes, sickle cell disease and the elderly.', 'Radiology & Radiation Safety'),
(2, 65, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Which of the following is classified as a positive (radio-opaque/white-appearing) contrast agent?', '["Vacuum/no contrast", "Carbon dioxide", "Barium", "Room air"]'::jsonb, 2, 'Positive contrast agents such as iodine-based media and barium are dense and appear white/opaque on imaging, unlike negative agents such as air or CO2 which appear dark/lucent.', 'Radiology & Radiation Safety'),
(2, 66, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Before administering iodinated contrast, the standard test dose protocol is to give:', '["1ml, then wait 5 minutes before proceeding", "10ml, then wait 30 minutes", "A test dose only in children", "The full dose immediately with no test"]'::jsonb, 0, 'A 1ml test dose is given, followed by a 5-minute wait to observe for an early reaction, before proceeding with the full contrast dose.', 'Radiology & Radiation Safety'),
(2, 67, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'An endotracheal tube tip on chest X-ray should ideally sit approximately how far above the carina?', '["In the right main bronchus", "At the level of the carina exactly", "10–12 cm above the carina", "3–5 cm above the carina"]'::jsonb, 3, 'The ETT tip should sit roughly 3–5 cm above the carina to avoid accidental right main bronchus intubation or extubation with neck movement.', 'Radiology & Radiation Safety'),
(2, 68, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A widened mediastinum on chest X-ray after trauma raises suspicion for:', '["Traumatic aortic injury/dissection", "Simple pneumonia", "Peptic ulcer perforation", "Normal anatomical variant in all patients"]'::jsonb, 0, 'A widened mediastinum following blunt chest trauma is a red-flag sign that warrants urgent evaluation for traumatic aortic injury.', 'Radiology & Radiation Safety'),
(2, 69, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The inverse square law in radiation protection means that doubling the distance from the source:', '["Reduces the dose to one quarter", "Doubles the dose", "Has no effect", "Halves the dose"]'::jsonb, 0, 'Distance is a simple, powerful protection.', 'Radiology & Radiation Safety'),
(2, 70, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A nasogastric tube''s position should be confirmed before feeding by:', '["pH testing of aspirate and/or X-ray confirmation", "Auscultation (''whoosh test'') alone", "Tube colour", "The patient''s verbal comfort report only"]'::jsonb, 0, 'Best practice for confirming NG tube position is pH testing of aspirate (ideally ≤5.5) and/or radiographic confirmation — auscultation alone is unreliable and is no longer recommended as a sole method.', 'Radiology & Radiation Safety'),
(2, 71, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'MRI scanning uses:', '["Ultraviolet light", "Gamma rays", "A strong magnetic field and radio waves, without ionising radiation", "X-rays"]'::jsonb, 2, 'Metal objects can become dangerous projectiles.', 'Radiology & Radiation Safety'),
(2, 72, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Barium contrast studies are absolutely contraindicated when there is suspicion of:', '["Simple constipation", "Bowel perforation", "Mild gastritis", "Uncomplicated reflux"]'::jsonb, 1, 'Barium leaking into the peritoneum through a perforation causes barium peritonitis and adhesions, which is life-threatening — water-soluble contrast is used instead if perforation is suspected.', 'Radiology & Radiation Safety'),
(2, 73, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Radiographic confirmation of correct nasogastric tube placement shows the tip:', '["Below the diaphragm, in the stomach", "In the right lung field", "At the level of the carina", "Coiled in the oesophagus"]'::jsonb, 0, 'A correctly placed NG tube''s tip is seen on X-ray crossing the diaphragm and lying within the stomach, well below the diaphragm and away from the bronchial tree.', 'Radiology & Radiation Safety'),
(2, 74, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'CT pulmonary angiography is the imaging investigation of choice to diagnose:', '["Simple rib fracture", "Pulmonary embolism", "Peptic ulcer disease", "Osteoarthritis"]'::jsonb, 1, 'CT pulmonary angiography directly visualises contrast-filled pulmonary arteries and is the standard imaging test to confirm or exclude pulmonary embolism.', 'Radiology & Radiation Safety'),
(2, 75, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A patient develops sudden chest pain and dyspnoea after central line insertion. A chest X-ray shows a hyperlucent area with absent lung markings on the same side. This confirms:', '["Pneumothorax, a recognised complication of central line insertion", "Successful catheter placement with no complication", "Pleural effusion", "Normal post-procedure findings"]'::jsonb, 0, 'A hyperlucent area with absent lung markings after central line insertion confirms pneumothorax, a well-recognised procedural complication requiring prompt management.', 'Radiology & Radiation Safety'),
(2, 76, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A nurse develops a rash on the hands after wearing powdered latex gloves. The first step is to:', '["Continue using the same gloves", "Wear two pairs of the same gloves", "Apply steroid cream and ignore it", "Report to occupational health for assessment"]'::jsonb, 3, 'Latex-free alternatives should be provided.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 77, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Prolonged standing in theatre is best managed by:', '["Wearing high heels", "Skipping breaks", "Anti-fatigue mats, supportive footwear and changing position", "Standing completely still"]'::jsonb, 2, 'It reduces back and leg strain.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 78, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Laser hazards to staff include eye injury, skin burns and:', '["Fire and inhalation of laser plume", "Hearing loss", "Hair loss", "Low blood sugar"]'::jsonb, 0, 'Use correct eyewear and smoke evacuation.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 79, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Bullying and harassment at work should be:', '["Accepted as part of the job", "Ignored", "Reported and dealt with according to policy", "Handled by revenge"]'::jsonb, 2, 'It harms staff health and patient safety.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 80, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Workplace stress among theatre nurses can be reduced by:', '["Ignoring complaints", "Blaming staff for errors", "Longer shifts without breaks", "Adequate staffing, support and clear communication"]'::jsonb, 3, 'Employee assistance programmes may also help.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 81, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'The RACE fire acronym stands for:', '["Remove, Ask, Call, Escape", "Rescue, Alarm, Contain, Extinguish/Evacuate", "Respond, Act, Clean, Evaluate", "Run, Alert, Close, Exit"]'::jsonb, 1, 'Remove people from danger first.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 82, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A good working posture when using a computer at the nurses'' station includes:', '["Feet dangling", "Screen far below eye level", "Twisting the back to reach the keyboard", "Screen at eye level and feet flat on the floor"]'::jsonb, 3, 'Regular breaks reduce strain.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 83, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Fire drills in theatre are important because:', '["They waste time", "Fires never happen in theatre", "Staff need to know evacuation routes and roles", "They replace fire extinguishers"]'::jsonb, 2, 'Plan evacuation of anaesthetised patients.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 84, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Sharps injuries should be reported mainly so that:', '["The patient is informed only", "Risk can be assessed, treatment given and practices improved", "The ward is closed", "The nurse is punished"]'::jsonb, 1, 'Under-reporting hides risks.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 85, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Correct lifting technique includes:', '["Twisting while lifting", "Bending at the waist with straight legs", "Keeping the load close, bending the knees and keeping the back straight", "Holding the load at arm''s length"]'::jsonb, 2, 'Avoid lifting patients manually where possible.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 86, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Night shift work increases the risk of:', '["Improved diet", "Better alertness", "Lower stress", "Fatigue-related errors and sleep problems"]'::jsonb, 3, 'Rest breaks and good rota planning help.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 87, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Glutaraldehyde exposure can cause:', '["Improved breathing", "Asthma, skin irritation and eye irritation", "Better wound healing", "No effects"]'::jsonb, 1, 'Use it in ventilated areas with PPE, or substitute safer agents.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 88, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Lead aprons should be checked regularly for:', '["Size labels", "Colour changes only", "Their weight in kilograms", "Cracks and damage, and stored hung up, not folded"]'::jsonb, 3, 'Folding cracks the lead lining.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 89, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Occupational health records of staff should be:', '["Posted on the notice board", "Shared with all colleagues", "Kept confidential", "Given to patients"]'::jsonb, 2, 'Only shared with consent or legal need.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 90, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A nurse who is splashed in the eye with a patient''s blood should first:', '["Rub the eye dry", "Wait until the end of the shift", "Apply antibiotic ointment only", "Irrigate the eye with plenty of water or saline"]'::jsonb, 3, 'Then report and follow the exposure protocol.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 91, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'A client who was previously the primary breadwinner expresses distress about being unable to return to work after a spinal cord injury and struggles with the loss of that role within the family. This is best classified under which Roy adaptive mode?', '["Physiological-physical mode", "Interdependence mode", "Role function mode", "Self-concept/group identity mode"]'::jsonb, 2, 'The role function mode addresses the roles a person occupies in society (e.g., worker, parent) and how the person adapts to changes in those roles, such as loss of the breadwinner role after injury.', 'Nursing Theories'),
(2, 92, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Orem identified three types of nursing systems. One of them is:', '["Team nursing", "Individualised client care", "Wholly compensatory", "Primary nursing"]'::jsonb, 2, 'Orem''s three nursing systems are wholly compensatory, partly compensatory and supportive-educative.', 'Nursing Theories'),
(2, 93, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Which of the following is included among Henderson''s 14 basic needs?', '["Avoid dangers in the environment and avoid injuring others", "Maintain the normal line of defense against stressors", "Achieve pandimensional integrality with the environment", "Progress through the regulator and cognator coping subsystems"]'::jsonb, 0, '''Avoid dangers in the environment and avoid injuring others'' is one of Henderson''s 14 components of basic nursing care, addressing safety needs.', 'Nursing Theories'),
(2, 94, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Roy''s model describes two major internal control processes, or coping subsystems, that a person uses to adapt to stimuli. What are they?', '["The wholly compensatory and partly compensatory subsystems", "The core structure and flexible line of defense", "The self-care agency and therapeutic self-care demand", "The regulator and cognator subsystems"]'::jsonb, 3, 'Roy identifies the regulator subsystem, which responds automatically through neural, chemical, and endocrine processes, and the cognator subsystem, which responds through cognitive-emotive channels such as perception, learning, judgment, and emotion.', 'Nursing Theories'),
(2, 95, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Interpersonal relationship theory was propounded by', '["B.F. skinner", "Martha Rogers.", "Sigmoid Freud.", "Hildegard Peplau"]'::jsonb, 3, 'Hildegard Peplau developed the interpersonal relations theory of nursing.', 'Nursing Theories'),
(2, 96, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'An ''open system,'' as used in systems theory and in nursing models such as Neuman''s and Roy''s, is best defined as one that:', '["Has no boundary separating it from its environment", "Exists in complete isolation from all outside influences", "Exchanges matter, energy, and information with its environment", "Cannot be influenced by external stressors"]'::jsonb, 2, 'An open system continuously exchanges matter, energy, and information across its boundary with the surrounding environment, allowing for growth, adaptation, and change — this is how the human being is conceptualized in most nursing systems models.', 'Nursing Theories'),
(2, 97, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'General Systems Theory, foundational to many nursing conceptual models, is most closely associated with which theorist?', '["Abraham Maslow", "Virginia Henderson", "Ludwig von Bertalanffy", "Florence Nightingale"]'::jsonb, 2, 'Ludwig von Bertalanffy, a biologist, formulated General Systems Theory, which was later adapted by nurse theorists such as Neuman and Rogers to describe the person as a system interacting with the environment.', 'Nursing Theories'),
(2, 98, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Neuman describes three levels of prevention as intervention. Which level is aimed at strengthening the flexible line of defense BEFORE a stressor invades the client system?', '["Primary prevention", "Secondary prevention", "Tertiary prevention", "Quaternary prevention"]'::jsonb, 0, 'Primary prevention in Neuman''s model occurs before a stressor has invaded the system, aiming to reduce the possibility of encountering the stressor or to strengthen the flexible line of defense, such as through immunization or health teaching.', 'Nursing Theories'),
(2, 99, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Orem categorized self-care requisites into three types. Which of the following correctly lists them?', '["Primary, secondary, and tertiary self-care requisites", "Physiological, psychological, and spiritual self-care requisites", "Focal, contextual, and residual self-care requisites", "Universal, developmental, and health-deviation self-care requisites"]'::jsonb, 3, 'Orem identified universal self-care requisites (common to all humans, e.g., air, water, food), developmental self-care requisites (associated with developmental processes/life events), and health-deviation self-care requisites (arising from illness or injury).', 'Nursing Theories'),
(2, 100, 'Perioperative Mock — Day 6 Afternoon (Nov 2026)', 'Nursing Theories', 'Which of the following best describes the ''regulator'' coping subsystem in Roy''s model?', '["A subsystem used only for spiritual coping", "A subsystem exclusive to the role-function adaptive mode", "A subsystem that processes information through cognitive-emotive channels such as perception and learning", "A subsystem that responds automatically through neural, chemical, and endocrine processes"]'::jsonb, 3, 'The regulator subsystem is the automatic coping process involving neural, chemical, and endocrine responses, such as the physiological stress response.', 'Nursing Theories'),
(3, 1, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A test that shows positive when the true status is negative gives a:', '["False negative", "True positive", "False positive", "True negative"]'::jsonb, 2, 'A false positive is a positive test result when the true status is negative.', 'GST 403 · Research & Statistics'),
(3, 2, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The original source from which researcher collects information is', '["Tertiary source", "Both primary and secondary", "Secondary Source", "Primary Source"]'::jsonb, 3, 'The original, first-hand source of information is a primary source.', 'GST 403 · Research & Statistics'),
(3, 3, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Research conducted to find a solution to an immediate problem is:', '["Analytical research", "Action research", "Fundamental research", "A survey"]'::jsonb, 1, 'Action research is done to find a solution to an immediate, practical problem in a setting.', 'GST 403 · Research & Statistics'),
(3, 4, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A Blue print of Research work is called', '["Research tools", "Research design", "Research methods", "Research Problem"]'::jsonb, 1, 'A structured overall plan for conducting research is the research design.', 'GST 403 · Research & Statistics'),
(3, 5, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The independent variable refers to:', '["The aim of an experiment", "The variable manipulated or varied by the researcher", "A variable used only in the control group", "The variable that shows the effect of the manipulation"]'::jsonb, 1, 'The independent variable is the one the researcher manipulates. The dependent variable shows its effect.', 'GST 403 · Research & Statistics'),
(3, 6, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'For which of the following research questions would qualitative methods be most appropriate?', '["How does frequency of medication administration impact the degree of pain experienced following knee replacement surgery?", "Which pain medications decrease the need for sleep medication in elderly patients?", "Under what conditions does a decubitus ulcer heal most quickly?", "What is the meaning of health to farmer?"]'::jsonb, 3, '"What is the meaning of health to farmers?" explores meaning and experience, which suits qualitative methods.', 'GST 403 · Research & Statistics'),
(3, 7, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A hypothesis that describes a relationship between two variables is:', '["Relational", "Causal", "Descriptive", "Tentative"]'::jsonb, 0, 'A relational (associative) hypothesis states that two variables are related, without claiming cause.', 'GST 403 · Research & Statistics'),
(3, 8, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A core ethical requirement in human subjects research is that participation must be:', '["Mandatory for all eligible patients", "Compensated financially regardless of consent", "Determined solely by the researcher", "Voluntary, based on informed consent, without coercion"]'::jsonb, 3, 'Ethical research requires that participants voluntarily consent to participate after being fully informed, free from coercion or undue influence.', 'GST 403 · Research & Statistics'),
(3, 9, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A tentative proposition that is subject to testing is a:', '["Hypothesis", "Variable", "Concept", "Datum"]'::jsonb, 0, 'A hypothesis is a tentative statement about the relationship between variables, to be tested.', 'GST 403 · Research & Statistics'),
(3, 10, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The concrete observable events which represent the abstract concepts or constructs are called', '["Sample", "Variable", "Proposition", "Data"]'::jsonb, 1, 'Concrete, observable representations of abstract concepts are variables.', 'GST 403 · Research & Statistics'),
(3, 11, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Research undertaken for the sake of knowledge is:', '["Action research", "A survey", "A pilot study", "Pure research"]'::jsonb, 3, 'Pure (basic, fundamental) research seeks knowledge for its own sake. Applied and action research solve practical problems.', 'GST 403 · Research & Statistics'),
(3, 12, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A pilot study provides the opportunity to:', '["Publish the results early", "Test the research instrument", "Understand the research problem", "Test the research subjects"]'::jsonb, 1, 'A pilot study pre-tests the research instrument and procedures on a small group before the main study.', 'GST 403 · Research & Statistics'),
(3, 13, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A control group condition is applied in:', '["Descriptive research", "Experimental research", "Survey research", "Historical research"]'::jsonb, 1, 'Experimental research uses a control group to compare against the group receiving the intervention.', 'GST 403 · Research & Statistics'),
(3, 14, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Cause-and-effect relationships are best studied using which design?', '["Quasi-experimental design", "Non-experimental design", "Experimental design", "Prospective design"]'::jsonb, 2, 'True experimental designs (manipulation, control, randomisation) are best for testing cause-and-effect.', 'GST 403 · Research & Statistics'),
(3, 15, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A (Celsius) thermometer typifies which scale?', '["Ordinal", "Ratio", "Interval", "Nominal"]'::jsonb, 2, 'Celsius and Fahrenheit thermometers are interval scales: equal intervals but no true zero.', 'GST 403 · Research & Statistics'),
(3, 16, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'A family caregiver of a chronically critically ill ICU patient reports exhaustion, feeling overwhelmed by care responsibilities, and increasing strain in the relationship with the patient. The most appropriate NANDA-I diagnosis is:', '["Interrupted Family Processes", "Caregiver Role Strain", "Compromised Family Coping", "Ineffective Family Coping"]'::jsonb, 1, 'Caregiver Role Strain specifically describes difficulty in performing the family caregiver role, evidenced by exhaustion, feeling overwhelmed, and relational strain.', 'Nursing Process'),
(3, 17, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'Which assessment covers past medical history, family history, reason for admission, current medications, psychosocial and complete physical assessment?', '["Focused assessment", "Emergency assessment", "Ongoing assessment", "Initial assessment"]'::jsonb, 3, 'The initial (admission) assessment is comprehensive: history, family history, medications, psychosocial and full physical assessment.', 'Nursing Process'),
(3, 18, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'A nurse develops a care plan with the goal ''Patient will ambulate 50 metres independently by discharge.'' At reassessment, the patient can walk 30 metres with assistance. This goal should be documented as:', '["Completely unmet with no progress", "Fully met", "Partially met, requiring plan revision", "Not applicable"]'::jsonb, 2, 'Partial progress toward but not achieving the stated goal is documented as ''partially met,'' prompting reassessment and revision of the care plan.', 'Nursing Process'),
(3, 19, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'A nurse identifies the following: "Ineffective Breathing Pattern," "Anxiety," and "Deficient Knowledge regarding home medication regimen" for a postoperative client. Using Maslow''s hierarchy, which diagnosis should be given the HIGHEST priority?', '["Deficient Knowledge regarding home medication regimen", "All three are equal priority", "Ineffective Breathing Pattern", "Anxiety"]'::jsonb, 2, 'Physiological needs, including oxygenation and breathing, take precedence over psychosocial needs such as anxiety or knowledge deficits, per Maslow''s hierarchy.', 'Nursing Process'),
(3, 20, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'If a goal states a patient will gain 2kg in 4 weeks, and the patient gains only 1kg, the goal is classified as:', '["Cannot be evaluated", "Partially Met", "Met", "Not Met"]'::jsonb, 1, 'Some progress was made toward the goal, but the full target wasn''t reached, which is exactly what ''partially met'' describes.', 'Nursing Process'),
(3, 21, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'Which framework helps the nurse organise data collected from the patient?', '["Maslow''s hierarchy", "Nightingale''s environmental theory", "Roy''s adaptation model", "Gordon''s functional health patterns"]'::jsonb, 3, 'Gordon''s functional health patterns give a framework for organising assessment data.', 'Nursing Process'),
(3, 22, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'Nursing diagnoses differ from medical diagnoses mainly in that they are:', '["Dependent on the medical diagnosis for direction", "Concerned with psychosocial parameters only", "Concerned with human responses while medical diagnoses are concerned with pathology", "Concerned with caring while medical diagnoses are concerned with curing"]'::jsonb, 2, 'Nursing diagnoses describe human responses to health problems. Medical diagnoses identify disease or pathology.', 'Nursing Process'),
(3, 23, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'A nurse repositions a patient who complains of difficulty breathing. This is which phase of the nursing process?', '["Assessment", "Outcome identification", "Evaluation", "Implementation"]'::jsonb, 3, 'Repositioning the patient to ease breathing is carrying out a nursing action: implementation.', 'Nursing Process'),
(3, 24, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'Which of the following diagnostic statements contains an error because the etiology names something that cannot legally or ethically be documented as a "cause" by a nurse?', '["\"Ineffective Coping related to situational crisis\"", "\"Acute Pain related to surgical incision\"", "\"Impaired Skin Integrity related to inadequate nursing care\"", "\"Risk for Falls related to unsteady gait\""]'::jsonb, 2, 'Writing a diagnosis with an etiology that implicates staff negligence, such as "related to inadequate nursing care," is legally inadvisable and inappropriate.', 'Nursing Process'),
(3, 25, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'Assessing how a client copes with stress, what support systems are available, and the effectiveness of the client''s usual coping strategies falls under which Gordon pattern?', '["Role-relationship pattern", "Value-belief pattern", "Coping-stress tolerance pattern", "Health perception-health management pattern"]'::jsonb, 2, 'The coping-stress tolerance pattern examines the client''s general coping style, effectiveness of coping in terms of stress tolerance, and support systems available.', 'Nursing Process'),
(3, 26, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'A Nurse at HMC asked a patient to verbalise if he understood the information given during nursing care to the client according to a devised nursing care plan. During which step of the nursing process does such action take place?', '["Planning", "Evaluation", "Assessment", "Implementation"]'::jsonb, 1, 'Checking whether the patient understood and achieved the planned outcome is the Evaluation step.', 'Nursing Process'),
(3, 27, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'One of the stated advantages of the nursing process is that it:', '["Promotes decisions based on routine, unquestioned habits", "Promotes individualised care and evidence-based decisions", "Eliminates the need for reassessment", "Removes the need for documentation"]'::jsonb, 1, 'The structured, data-driven nature of the nursing process supports care tailored to the individual patient, avoiding purely routine-based decisions.', 'Nursing Process'),
(3, 28, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'The five steps of the nursing process, in order, are:', '["Assessment, diagnosis, planning, implementation, evaluation", "Diagnosis, assessment, planning, implementation, evaluation", "Implementation, planning, assessment, diagnosis, evaluation", "Planning, assessment, diagnosis, evaluation, implementation"]'::jsonb, 0, 'The nursing process (ADPIE) follows the sequence: Assessment, Diagnosis, Planning, Implementation, and Evaluation, providing a systematic framework for individualised patient care.', 'Nursing Process'),
(3, 29, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'A nurse made Mr Kay''s care plan on admission on Tuesday, then made another care plan for him on Wednesday''s shift. Wednesday''s plan is a(n):', '["Initial plan", "Discharge plan", "Ongoing plan", "Reviewed plan"]'::jsonb, 2, 'The initial plan is made on admission. Plans updated on later shifts as the patient''s status changes are ongoing plans.', 'Nursing Process'),
(3, 30, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Nursing Process', 'COLDSPA pain assessment falls under which functional health pattern?', '["Cognition and perception", "Sleep and rest", "Self-perception and self-concept", "Activity and exercise"]'::jsonb, 0, 'COLDSPA (Character, Onset, Location, Duration, Severity, Pattern, Associated factors) assesses pain, part of Gordon''s cognitive–perceptual pattern.', 'Nursing Process'),
(3, 31, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'Which leadership style encourages staff participation in decision-making?', '["Democratic", "Bureaucratic", "Autocratic", "Laissez-faire"]'::jsonb, 0, 'Democratic leadership actively involves staff in decision-making.', 'Management'),
(3, 32, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'Clinical audit is conducted mainly to:', '["Recruit nurses", "Discipline staff", "Increase hospital income", "Compare practice with standards"]'::jsonb, 3, 'Clinical audit compares actual practice against established standards to identify gaps for improvement.', 'Management'),
(3, 33, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'Which management function should always come first?', '["Controlling", "Organizing", "Planning", "Directing"]'::jsonb, 2, 'Planning sets the direction and goals that organizing, directing, and controlling all follow from, so it is the first management function.', 'Management'),
(3, 34, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'The five classic functions of management are best listed as:', '["Hiring, Firing, Paying, Training, Promoting", "Planning, Organising, Staffing, Directing, Controlling", "Assessing, Planning, Implementing, Evaluating, Documenting", "Diagnosing, Prescribing, Treating, Evaluating, Discharging"]'::jsonb, 1, 'The classic management functions are Planning, Organising, Staffing, Directing and Controlling.', 'Management'),
(3, 35, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'A staff nurse consistently exceeds performance expectations. The BEST management response is to:', '["Increase criticism", "Recognize and reward excellent performance", "Ignore the performance", "Assign all difficult patients to the nurse"]'::jsonb, 1, 'Recognising and rewarding strong performance reinforces and sustains it.', 'Management'),
(3, 36, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'A nurse manager estimates the number of nurses required for the ICU next year. This activity is known as:', '["Staff appraisal", "Human resource planning", "Staff orientation", "Supervision"]'::jsonb, 1, 'Forecasting future staffing needs is a form of human resource planning.', 'Management'),
(3, 37, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'An effective preceptor should primarily:', '["Guide, supervise, and support learning", "Delegate all work to students", "Criticize new staff publicly", "Avoid giving feedback"]'::jsonb, 0, 'An effective preceptor''s core role is to guide, supervise, and support the learner''s development.', 'Management'),
(3, 38, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'Which leadership style is most appropriate during cardiopulmonary resuscitation?', '["Autocratic", "Democratic", "Laissez-faire", "Transformational"]'::jsonb, 0, 'During CPR, clear, rapid, directive instructions from one leader are needed, making autocratic leadership most appropriate in that emergency moment.', 'Management'),
(3, 39, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'As an ICU manager you are aware that a formal document that most supervisors or managers keep for future reference is called', '["Incident writing", "Report writing", "Incident report", "Incident reporting"]'::jsonb, 2, 'A formal record kept by supervisors for future reference describing an event is an incident report.', 'Management'),
(3, 40, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'The ''5 Rights of Delegation'' include right task, right circumstance, right person, right direction/communication, and:', '["Right payment", "Right documentation only", "Right uniform", "Right supervision/evaluation"]'::jsonb, 3, 'The 5 Rights of Delegation are: right task, right circumstance, right person, right direction/communication, and right supervision/evaluation.', 'Management'),
(3, 41, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'Which task should NOT be delegated to a nursing assistant?', '["Bed making", "Transporting stable patients", "Feeding a stable patient", "Assessment of pain"]'::jsonb, 3, 'Clinical judgement tasks like pain assessment require nursing scope of practice and should not be delegated to unlicensed assistive personnel.', 'Management'),
(3, 42, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'Which quality tool is commonly used to identify the underlying causes of a problem?', '["Organizational chart", "Fishbone (Ishikawa) diagram", "Duty roster", "Leave register"]'::jsonb, 1, 'The fishbone (Ishikawa) diagram is a structured tool for identifying the underlying causes of a problem.', 'Management'),
(3, 43, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'When mediating conflict between staff, a nurse manager should ideally:', '["Resolve the conflict publicly in front of patients", "Avoid addressing it entirely", "Act as a neutral mediator", "Take sides with the more senior staff member"]'::jsonb, 2, 'A manager who is seen to favour one side loses the trust needed to mediate fairly between the two parties.', 'Management'),
(3, 44, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'A nurse manager encourages innovation and professional growth among staff. This demonstrates:', '["Bureaucratic leadership", "Autocratic leadership", "Transformational leadership", "Transactional leadership"]'::jsonb, 2, 'Encouraging innovation and staff growth is characteristic of transformational leadership.', 'Management'),
(3, 45, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'Management', 'The abbreviation FIFO in store management means:', '["First Into Final Order", "Fast Inventory Follow-up Operation", "First In, First Out", "Final Item First Out"]'::jsonb, 2, 'FIFO stands for First In, First Out, a stock rotation method.', 'Management'),
(3, 46, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The Helsinki Declaration establishes that:', '["Subject wellbeing takes precedence over the interests of science/society", "Science''s interests always come first", "Consent is optional if the research benefits many people", "Only adult subjects may ever be studied"]'::jsonb, 0, 'This declaration puts the individual research subject''s welfare above any broader scientific or societal gain.', 'GSE 420 · Ethico-legal Aspects'),
(3, 47, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'What is the most common source of malpractice for nurses?', '["Medication errors", "Privacy violations", "Negligent delegation", "HIPPA complaints"]'::jsonb, 0, 'Medication errors are the most commonly cited source of nursing malpractice claims.', 'GSE 420 · Ethico-legal Aspects'),
(3, 48, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A document that lists the medical treatment a person chooses to refuse if unable to make decisions is the:', '["Living will", "Informed consent", "Durable power of attorney", "Advance directives"]'::jsonb, 0, 'A living will is the advance directive that lists the treatments a person chooses to refuse if they can no longer decide. A durable power of attorney names a proxy decision-maker instead.', 'GSE 420 · Ethico-legal Aspects'),
(3, 49, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A family disagrees with a DNR order for a patient with metastatic lung cancer. The nurse involves:', '["Risk management", "Social services", "Hospital security", "Ethics committee"]'::jsonb, 3, 'An ethics committee helps resolve conflicts about goals of care.', 'GSE 420 · Ethico-legal Aspects'),
(3, 50, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The Belmont Report''s 3 core ethical principles are:', '["Autonomy, Beneficence, Justice", "Consent, Privacy, Fairness", "Safety, Dignity, Respect", "Honesty, Accuracy, Transparency"]'::jsonb, 0, 'These three principles form the foundational framework most modern research ethics guidelines build upon.', 'GSE 420 · Ethico-legal Aspects'),
(3, 51, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A competent patient''s living will refuses aggressive cancer treatment, but the physician insists on chemotherapy for the patient''s benefit. The physician is exercising:', '["Ideal beneficence", "Respect for autonomy", "Veracity", "Paternalism"]'::jsonb, 3, 'Paternalism is overriding a competent patient''s known wishes (such as a living will refusing aggressive treatment) "for their own good".', 'GSE 420 · Ethico-legal Aspects'),
(3, 52, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The core legal/professional principle behind nursing documentation is best summarised as:', '["Documentation is optional if care was given correctly", "Only negative events need to be documented", "Documentation can be completed weeks later without issue", "''If it wasn''t documented, it wasn''t done''"]'::jsonb, 3, 'Accurate, timely documentation is a nurse''s primary legal protection — undocumented care is very difficult to prove was ever given.', 'GSE 420 · Ethico-legal Aspects'),
(3, 53, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The ''Beneficence'' principle obligates the nurse to:', '["Simply avoid causing harm", "Always follow the patient''s exact instructions regardless of clinical judgement", "Actively act in ways that promote the patient''s wellbeing and best interests", "Distribute resources equally"]'::jsonb, 2, 'Beneficence goes beyond avoiding harm (non-maleficence) — it obligates the nurse to actively act for the patient''s good and wellbeing.', 'GSE 420 · Ethico-legal Aspects'),
(3, 54, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A nursing instructor tells students that the most important principle when caring for patients is to do no harm. This principle is:', '["Non-maleficence", "Justice", "Beneficence", "Veracity"]'::jsonb, 0, 'Non-maleficence means "first, do no harm". It runs from the Hippocratic Oath to the Nightingale Pledge.', 'GSE 420 · Ethico-legal Aspects'),
(3, 55, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A failure in professional duty, practice or skill that leads to injury or harm to the patient is termed as-', '["Malpractice", "Negligence", "Crime", "Misunderstanding"]'::jsonb, 0, 'A professional failure causing patient harm is malpractice.', 'GSE 420 · Ethico-legal Aspects'),
(3, 56, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Breach of patient confidentiality without lawful justification may expose a nurse to which type of legal action?', '["Civil liability for breach of confidentiality/privacy", "No consequence, since nurses have full immunity", "Automatic loss of citizenship", "Only a verbal warning with no formal process"]'::jsonb, 0, 'Unjustified disclosure of confidential patient information can expose a nurse to civil liability for breach of confidentiality.', 'GSE 420 · Ethico-legal Aspects'),
(3, 57, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The Nuremberg Code primarily established the requirement for:', '["Government funding approval", "Voluntary consent and subject welfare", "Peer review of all studies", "Statistical significance testing"]'::jsonb, 1, 'This code emerged after WWII specifically to ensure research subjects freely agree to participate and that their welfare is protected.', 'GSE 420 · Ethico-legal Aspects'),
(3, 58, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'What is informed consent in nursing?', '["The process of providing information to a patient about the risks and benefits of a specific procedure or treatment", "The process of respecting patients right to refuse or withdraw from a specific procedure or treatment", "The process of obtaining permission from a patient to perform a specific procedure or treatment", "The process of ensuring that a patient understands and agrees to a specific procedure or treatment"]'::jsonb, 3, 'Informed consent centres on the patient genuinely understanding and agreeing to a procedure.', 'GSE 420 · Ethico-legal Aspects'),
(3, 59, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A patient’s advance directive states no intubation. During respiratory arrest, the nurse should:', '["Ask family for consent", "Follow the advance directive", "Intubate emergently", "Start non-invasive ventilation"]'::jsonb, 1, 'Advance directives are legally binding; providers must honor them.', 'GSE 420 · Ethico-legal Aspects'),
(3, 60, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'In nursing ethics, the principle of Justice specifically requires:', '["Treating all patients equally regardless of background", "Ignoring resource limitations entirely", "Giving preferential treatment to paying patients", "Prioritising patients by social status"]'::jsonb, 0, 'Justice in nursing means a patient''s background should never influence the quality of care they receive.', 'GSE 420 · Ethico-legal Aspects'),
(3, 61, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'An example of a nurse-led business in perioperative care is:', '["Selling cars", "Running a bank", "Building roads", "A private home-care service for post-operative patients"]'::jsonb, 3, 'Nurses can also offer training or consultancy.', 'GST 408 · Entrepreneurship'),
(3, 62, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A partnership business is:', '["A charity with no owners", "Owned by two or more people who share profits and liabilities", "Owned by the government only", "Owned by one person only"]'::jsonb, 1, 'A partnership agreement should be written.', 'GST 408 · Entrepreneurship'),
(3, 63, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Working capital refers to:', '["Personal savings only", "Money available for day-to-day running costs", "Money for buying buildings", "Profit after tax"]'::jsonb, 1, 'Current assets minus current liabilities.', 'GST 408 · Entrepreneurship'),
(3, 64, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Bookkeeping is important in a small business mainly to:', '["Decorate the office", "Advertise", "Keep accurate records of income and spending", "Recruit staff only"]'::jsonb, 2, 'It supports tax returns and planning.', 'GST 408 · Entrepreneurship'),
(3, 65, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Profit is calculated as:', '["Revenue plus costs", "Revenue divided by costs", "Total costs minus revenue", "Total revenue minus total costs"]'::jsonb, 3, 'A loss occurs when costs exceed revenue.', 'GST 408 · Entrepreneurship'),
(3, 66, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A loan from a bank for business must usually be supported by:', '["A promise to pay back someday", "A business plan and collateral or guarantee", "A recommendation from a friend only", "Nothing at all"]'::jsonb, 1, 'Banks assess the risk of repayment.', 'GST 408 · Entrepreneurship'),
(3, 67, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Ethical business practice for a nurse entrepreneur includes:', '["Ignoring patient confidentiality", "Honest advertising and following professional standards", "Avoiding registration", "Making false health claims"]'::jsonb, 1, 'The Nursing and Midwifery Council''s code still applies.', 'GST 408 · Entrepreneurship'),
(3, 68, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Return on investment (ROI) measures:', '["The profit made compared with the money invested", "The number of staff", "The size of the office", "The number of customers only"]'::jsonb, 0, 'Higher ROI means a more profitable investment.', 'GST 408 · Entrepreneurship'),
(3, 69, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A feasibility study before starting a business assesses:', '["Only the owner''s age", "The colour of the building", "Whether the idea is practical and likely to succeed", "The weather"]'::jsonb, 2, 'It looks at market, costs and risks.', 'GST 408 · Entrepreneurship'),
(3, 70, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A key characteristic of a successful entrepreneur is:', '["Waiting for others to act", "Fear of change", "Willingness to take calculated risks", "Avoiding decisions"]'::jsonb, 2, 'Creativity and persistence are also important.', 'GST 408 · Entrepreneurship'),
(3, 71, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'According to function, computers are classified as:', '["Automatic and manual", "Analogue, digital and hybrid", "Electronic and battery-powered", "Laptop, desktop and hand-held"]'::jsonb, 1, 'By function (how they process data), computers are analogue, digital or hybrid.', 'GST 405 · Computer Studies'),
(3, 72, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'The four main functional components of a standard computer are:', '["Laptop, desktop, tablet and hand-held", "Keyboard, mouse, monitor and CPU", "Input, process, output and memory (storage)", "Hardware, software, system apps and applications"]'::jsonb, 2, 'A computer''s four main functional components are input, processing, output and storage (memory).', 'GST 405 · Computer Studies'),
(3, 73, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'An advantage of the electronic medication administration record (eMAR) over paper MARs is:', '["Real-time updates and reduced transcription error risk", "It cannot be updated in real time", "It eliminates the need for the five rights of administration", "It requires no cross-check with the pharmacy system"]'::jsonb, 0, 'eMAR systems update in real time and are typically integrated with pharmacy and BCMA systems, reducing transcription errors compared to handwritten paper MARs.', 'GST 405 · Computer Studies'),
(3, 74, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'A phishing email pretending to be from IT asking staff to ''confirm'' their password is an example of:', '["A required annual login refresh", "A harmless marketing email", "A legitimate security update", "A social engineering cybersecurity threat"]'::jsonb, 3, 'Phishing is a social engineering technique that tricks users into revealing credentials or sensitive data, a major cybersecurity threat in healthcare settings.', 'GST 405 · Computer Studies'),
(3, 75, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Sharing your personal EHR login credentials with a colleague is:', '["Only a problem if a wrong entry is made", "Acceptable if they are busy", "A breach of data confidentiality and accountability", "Required by hospital policy"]'::jsonb, 2, 'Login credentials are personal and tied to individual accountability; sharing them breaches confidentiality policy and undermines the audit trail of who accessed or changed a record.', 'GST 405 · Computer Studies'),
(3, 76, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Which of the following is an example of secondary (long-term) storage?', '["Hard disk drive", "RAM", "CPU register", "CPU cache"]'::jsonb, 0, 'Secondary storage devices such as hard disks, USB flash drives and optical disks retain data long-term, unlike RAM which is volatile working memory.', 'GST 405 · Computer Studies'),
(3, 77, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'If a nurse suspects a patient data breach has occurred, the appropriate first action is to:', '["Ignore it if no harm seems obvious", "Report it immediately according to institutional policy", "Discuss it publicly with colleagues on social media", "Delete the affected records"]'::jsonb, 1, 'Suspected breaches must be reported promptly through official channels so they can be investigated, contained, and, where required, disclosed per policy/regulation.', 'GST 405 · Computer Studies'),
(3, 78, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'The Central Processing Unit (CPU) of a computer is primarily responsible for:', '["Providing internet connectivity only", "Executing instructions and processing data", "Permanent data storage only", "Displaying output on the monitor only"]'::jsonb, 1, 'The CPU is the computer''s ''brain'' — it fetches, decodes and executes instructions, performing the actual data processing.', 'GST 405 · Computer Studies'),
(3, 79, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Protecting electronic access to client data primarily relies on which of the following measures?', '["Disabling all data backups", "Leaving all records openly accessible to any staff member for convenience", "User authentication (passwords/logins), access controls and audit trails", "Printing all records to avoid computer use entirely"]'::jsonb, 2, 'Controlled access via authentication, role-based permissions and audit trails is a core safeguard for protecting confidential electronic client data.', 'GST 405 · Computer Studies'),
(3, 80, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Computer software is classified into:', '["Special, general and specific packages", "Word, PowerPoint and Excel", "System, application and utility software", "Personal and industrial software"]'::jsonb, 2, 'Software is broadly system software (including utilities) and application software.', 'GST 405 · Computer Studies'),
(3, 81, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'The method and process of facilitating the peaceful ending of a conflict is called:', '["Conflict resolution", "Conflict", "Psychological trauma", "Fight"]'::jsonb, 0, 'Conflict resolution is the process of bringing a conflict to a peaceful end.', 'GST 401 · Behavioural Science'),
(3, 82, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Erikson''s stage for adolescents is:', '["Industry versus inferiority", "Trust versus mistrust", "Integrity versus despair", "Identity versus role confusion"]'::jsonb, 3, 'Body image after surgery is especially important to teenagers.', 'GST 401 · Behavioural Science'),
(3, 83, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A nurse is caring for a client who is in acute respiratory distress and also expressing anxiety about an upcoming diagnostic test. Using Maslow''s hierarchy to prioritize care, the nurse should address which need FIRST?', '["The client''s airway and oxygenation status (physiological need)", "The client''s need for self-esteem and a sense of accomplishment", "The client''s need for social interaction with family", "The client''s anxiety about the diagnostic test (safety/psychological need)"]'::jsonb, 0, 'Physiological needs, including oxygenation, take priority over higher-level needs such as psychological safety or emotional reassurance according to Maslow''s hierarchy, making airway/breathing the first priority.', 'GST 401 · Behavioural Science'),
(3, 84, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A nurse is organizing assessment data using Maslow''s Hierarchy of Needs. Which finding would be prioritized at the most basic (foundational) level?', '["Client has an oxygen saturation of 84% on room air", "Client expresses low self-esteem", "Client reports feeling isolated from friends", "Client is worried about returning to work"]'::jsonb, 0, 'Maslow''s hierarchy places physiological needs, such as oxygenation, at the foundational level, taking priority over psychosocial or self-esteem needs.', 'GST 401 · Behavioural Science'),
(3, 85, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'The ''sick role'' described by Parsons includes the right to be excused from normal duties and the duty to:', '["Stay ill as long as possible", "Hide the illness", "Seek help and try to get well", "Refuse all treatment"]'::jsonb, 2, 'Society expects the sick person to cooperate with care.', 'GST 401 · Behavioural Science'),
(3, 86, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A nurse is caring for four clients simultaneously. Which client''s need should the nurse prioritize FIRST according to Maslow''s hierarchy of needs?', '["A client requesting a chaplain visit for spiritual support", "A client expressing embarrassment about needing help with bathing", "A client with an oxygen saturation of 84% on room air", "A client worried about being discharged without family support"]'::jsonb, 2, 'A critically low oxygen saturation represents an urgent physiological need (oxygenation) that takes priority over safety, love/belonging, and esteem needs according to Maslow''s hierarchy.', 'GST 401 · Behavioural Science'),
(3, 87, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Non-verbal communication includes:', '["Telephone calls only", "Written reports only", "Facial expression, posture and eye contact", "Emails"]'::jsonb, 2, 'It often carries more meaning than words.', 'GST 401 · Behavioural Science'),
(3, 88, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Behavioural Science is defined by the American Psychological Association as:', '["A discipline in which humans relate with their environment.", "Discipline of applied behavioural analysis which involves applying behavioural principles in practice setting.", "Subject of studying human behaviours.", "Discipline that uses systemic observation and experimentation in the scientific study of human and non-human actions and reactions."]'::jsonb, 3, 'APA defines behavioural science as the systematic scientific study of human/non-human actions and reactions.', 'GST 401 · Behavioural Science'),
(3, 89, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Projection as a defence mechanism means:', '["Turning feelings into physical symptoms", "Returning to childish behaviour", "Refusing to accept reality", "Attributing one''s own unacceptable feelings to others"]'::jsonb, 3, 'E.g. an angry patient accusing the nurse of being angry.', 'GST 401 · Behavioural Science'),
(3, 90, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A client recovering from a mastectomy tells the nurse, ''I''m worried my husband won''t find me attractive anymore and that we''ll grow apart.'' This concern is most directly related to which level of Maslow''s hierarchy?', '["Love and belonging needs", "Safety and security needs", "Physiological needs", "Self-actualization needs"]'::jsonb, 0, 'Concerns about intimacy and connectedness within a significant relationship correspond to the love and belonging level of Maslow''s hierarchy.', 'GST 401 · Behavioural Science'),
(3, 91, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'The suffix ''-otomy'' means:', '["Surgical removal", "Repair", "Making a permanent opening", "Cutting into"]'::jsonb, 3, 'E.g. laparotomy, tracheotomy.', 'GST 400 · Use of English'),
(3, 92, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'Which of these words is spelt correctly?', '["Necesary", "Neccesary", "Neccessary", "Necessary"]'::jsonb, 3, 'One ''c'' and double ''s''.', 'GST 400 · Use of English'),
(3, 93, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct preposition: ''The patient complained ___ severe pain.''', '["with", "of", "at", "for"]'::jsonb, 1, 'We complain of symptoms and about situations.', 'GST 400 · Use of English'),
(3, 94, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correctly punctuated sentence:', '["The surgeons'' instrument''s were ready.", "The surgeon''s instrument''s were ready.", "The surgeons instrument''s were ready.", "The surgeon''s instruments were ready."]'::jsonb, 3, 'The apostrophe shows possession, not plurals.', 'GST 400 · Use of English'),
(3, 95, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'The suffix ''-plasty'' means:', '["Bleeding", "Inflammation", "Removal", "Surgical repair or reshaping"]'::jsonb, 3, 'E.g. rhinoplasty, arthroplasty.', 'GST 400 · Use of English'),
(3, 96, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct sentence:', '["Fewer patients attended the clinic today.", "Less patients attended the clinic today.", "Lesser patients attended the clinic today.", "Few patients attends the clinic today."]'::jsonb, 0, '''Fewer'' is used with countable nouns.', 'GST 400 · Use of English'),
(3, 97, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the word opposite in meaning to ''acute'':', '["Sharp", "Chronic", "Severe", "Sudden"]'::jsonb, 1, 'Acute means sudden onset; chronic means long-standing.', 'GST 400 · Use of English'),
(3, 98, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'The prefix ''hyper-'' means:', '["Above or excessive", "Around", "Below or deficient", "Without"]'::jsonb, 0, 'E.g. hypertension, hyperglycaemia.', 'GST 400 · Use of English'),
(3, 99, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the sentence written in the correct tense for a nursing record of past care:', '["The patient turns at 14:00 yesterday.", "The patient will be turned at 14:00 yesterday.", "The patient is turn at 14:00.", "The patient was turned at 14:00."]'::jsonb, 3, 'Records describe care already given in the past tense.', 'GST 400 · Use of English'),
(3, 100, 'Perioperative Mock — Day 6 Night (Nov 2026)', 'GST 400 · Use of English', 'The word ''bilateral'' means:', '["On both sides", "On one side", "Above", "Below"]'::jsonb, 0, 'Unilateral means on one side.', 'GST 400 · Use of English');
